package api

import (
	"encoding/json"
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/notification-service/internal/delivery"
	"github.com/luwa07832/notification-service/internal/store"
)

const (
	codeInvalidRecord = "INVALID_DELIVERY_RECORD"
	codeInvalidQuery  = "INVALID_DELIVERY_QUERY"
	codeRecordMissing = "DELIVERY_RECORD_NOT_FOUND"
	codeStorageDown   = "STORAGE_UNAVAILABLE"
)

func respondError(c *gin.Context, status int, code, message string) {
	c.JSON(status, gin.H{"error": gin.H{"code": code, "message": message}})
}

// createDeliveryRecord handles POST /api/v1/delivery-records. It validates the
// submitted attempt, registers it once, and returns the stored record.
func createDeliveryRecord(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		var input delivery.RecordInput
		decoder := json.NewDecoder(c.Request.Body)
		if err := decoder.Decode(&input); err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidRecord, "delivery record payload is not valid")
			return
		}

		record, err := delivery.NewRecord(input)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidRecord, "delivery record payload is not valid")
			return
		}

		saved, err := st.CreateDeliveryRecord(c.Request.Context(), record)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		c.JSON(http.StatusCreated, saved)
	}
}

// getDeliveryRecord handles GET /api/v1/delivery-records/:id.
func getDeliveryRecord(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		record, ok, err := st.GetDeliveryRecord(c.Request.Context(), c.Param("id"))
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		if !ok {
			respondError(c, http.StatusNotFound, codeRecordMissing, "delivery record was not found")
			return
		}
		c.JSON(http.StatusOK, record)
	}
}

// listDeliveryRecords handles GET /api/v1/delivery-records?channel=&start=&end=.
// The time range is half-open: start <= occurred_at < end.
func listDeliveryRecords(st *store.Store) gin.HandlerFunc {
	return func(c *gin.Context) {
		query, err := delivery.NewQuery(
			c.Query("channel"),
			c.Query("start"),
			c.Query("end"),
		)
		if err != nil {
			respondError(c, http.StatusBadRequest, codeInvalidQuery, "delivery query parameters are not valid")
			return
		}

		records, err := st.ListDeliveryRecords(c.Request.Context(), query)
		if err != nil {
			respondError(c, http.StatusServiceUnavailable, codeStorageDown, "delivery record storage is not available")
			return
		}
		if records == nil {
			records = []delivery.Record{}
		}
		c.JSON(http.StatusOK, gin.H{"records": records})
	}
}
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"time"

	"github.com/google/uuid"

	"github.com/luwa07832/notification-service/internal/delivery"
)

// ErrStorageUnavailable marks a failed storage call. The HTTP layer maps it to
// the published STORAGE_UNAVAILABLE response instead of leaking driver errors.
var ErrStorageUnavailable = errors.New("storage is unavailable")

// storedTimeFormat is a fixed-width UTC layout. Fixed width makes the text
// column sort in chronological order and keeps range comparisons exact.
const storedTimeFormat = "2006-01-02T15:04:05.000000000Z"

// CreateDeliveryRecord inserts one delivery attempt. Every attempt gets its
// own row and its own id; retries never overwrite earlier failure reasons.
func (s *Store) CreateDeliveryRecord(ctx context.Context, record delivery.Record) (delivery.Record, error) {
	record.ID = uuid.NewString()
	storedAt := record.OccurredAt.UTC().Format(storedTimeFormat)
	_, err := s.db.ExecContext(ctx,
		`INSERT INTO delivery_records
		    (id, template_id, channel, occurred_at, status, retry_count, failure_reason)
		  VALUES (?, ?, ?, ?, ?, ?, ?)`,
		record.ID, record.TemplateID, record.Channel, storedAt,
		record.Status, record.RetryCount, record.FailureReason,
	)
	if err != nil {
		return delivery.Record{}, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	return record, nil
}

// GetDeliveryRecord loads one record by id. The boolean is false when no row
// exists; that is not a storage failure.
func (s *Store) GetDeliveryRecord(ctx context.Context, id string) (delivery.Record, bool, error) {
	row := s.db.QueryRowContext(ctx,
		`SELECT id, template_id, channel, occurred_at, status, retry_count, failure_reason
		   FROM delivery_records WHERE id = ?`, id)

	record, err := scanDeliveryRecord(row)
	if errors.Is(err, sql.ErrNoRows) {
		return delivery.Record{}, false, nil
	}
	if err != nil {
		return delivery.Record{}, false, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	return record, true, nil
}

// ListDeliveryRecords returns registered records for one channel whose
// occurrence time falls in the half-open [start, end) range, ordered by
// occurrence time ascending.
func (s *Store) ListDeliveryRecords(ctx context.Context, query delivery.Query) ([]delivery.Record, error) {
	rows, err := s.db.QueryContext(ctx,
		`SELECT id, template_id, channel, occurred_at, status, retry_count, failure_reason
		   FROM delivery_records
		  WHERE channel = ? AND occurred_at >= ? AND occurred_at < ?
		  ORDER BY occurred_at ASC, id ASC`,
		query.Channel,
		query.Start.UTC().Format(storedTimeFormat),
		query.End.UTC().Format(storedTimeFormat),
	)
	if err != nil {
		return nil, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	defer rows.Close()

	var records []delivery.Record
	for rows.Next() {
		record, err := scanDeliveryRecord(rows)
		if err != nil {
			return nil, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
		}
		records = append(records, record)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
	}
	return records, nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanDeliveryRecord(scanner rowScanner) (delivery.Record, error) {
	var record delivery.Record
	var occurredAt string
	if err := scanner.Scan(
		&record.ID, &record.TemplateID, &record.Channel, &occurredAt,
		&record.Status, &record.RetryCount, &record.FailureReason,
	); err != nil {
		return delivery.Record{}, err
	}
	parsedAt, err := time.Parse(storedTimeFormat, occurredAt)
	if err != nil {
		return delivery.Record{}, err
	}
	record.OccurredAt = parsedAt.UTC()
	return record, nil
}
// Package delivery owns the delivery-result record contract: the fields registered
// after every real delivery attempt and the rules every record must satisfy.
package delivery

import (
	"errors"
	"strings"
	"time"
)

// Sentinel validation errors. The HTTP layer maps them to the published error codes.
var (
	ErrInvalidRecord = errors.New("invalid delivery record")
	ErrInvalidQuery  = errors.New("invalid delivery query")
)

// Allowed delivery channels.
var channels = map[string]struct{}{
	"sms":    {},
	"email":  {},
	"push":   {},
	"in_app": {},
}

// IsAllowedChannel reports whether channel is one the service can register.
func IsAllowedChannel(channel string) bool {
	_, ok := channels[channel]
	return ok
}

// IsAllowedStatus reports whether status is one of the four published states.
func IsAllowedStatus(status string) bool {
	switch status {
	case StatusPending, StatusRetrying, StatusSucceeded, StatusFailed:
		return true
	}
	return false
}

// Published delivery statuses.
const (
	StatusPending   = "pending"
	StatusRetrying  = "retrying"
	StatusSucceeded = "succeeded"
	StatusFailed    = "failed"
)

// RecordInput is the payload submitted through the public write entry.
// RetryCount is a pointer so a missing or null value is rejected the same
// way as a non-integer value.
type RecordInput struct {
	TemplateID    string `json:"template_id"`
	Channel       string `json:"channel"`
	OccurredAt    string `json:"occurred_at"`
	Status        string `json:"status"`
	RetryCount    *int   `json:"retry_count"`
	FailureReason string `json:"failure_reason"`
}

// Record is a successfully registered delivery attempt. Every attempt is an
// independent row; repeated notifications never overwrite earlier records.
type Record struct {
	ID            string    `json:"id"`
	TemplateID    string    `json:"template_id"`
	Channel       string    `json:"channel"`
	OccurredAt    time.Time `json:"occurred_at"`
	Status        string    `json:"status"`
	RetryCount    int       `json:"retry_count"`
	FailureReason string    `json:"failure_reason"`
}

// NewRecord validates input and builds the record as it will be stored. The id
// is assigned by the storage layer when the insert actually succeeds.
func NewRecord(in RecordInput) (Record, error) {
	templateID := strings.TrimSpace(in.TemplateID)
	if templateID == "" {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedChannel(strings.TrimSpace(in.Channel)) || in.Channel != strings.TrimSpace(in.Channel) {
		return Record{}, ErrInvalidRecord
	}
	occurredAt, err := time.Parse(time.RFC3339, in.OccurredAt)
	if err != nil {
		return Record{}, ErrInvalidRecord
	}
	if !IsAllowedStatus(in.Status) {
		return Record{}, ErrInvalidRecord
	}
	if in.RetryCount == nil || *in.RetryCount < 0 {
		return Record{}, ErrInvalidRecord
	}
	switch in.Status {
	case StatusFailed, StatusRetrying:
		if strings.TrimSpace(in.FailureReason) == "" {
			return Record{}, ErrInvalidRecord
		}
	case StatusPending, StatusSucceeded:
		if in.FailureReason != "" {
			return Record{}, ErrInvalidRecord
		}
	}
	return Record{
		TemplateID:    templateID,
		Channel:       in.Channel,
		OccurredAt:    occurredAt.UTC(),
		Status:        in.Status,
		RetryCount:    *in.RetryCount,
		FailureReason: in.FailureReason,
	}, nil
}

// Query is a validated channel plus half-open time range query.
type Query struct {
	Channel string
	Start   time.Time
	End     time.Time
}

// NewQuery validates the query parameters. The range is [start, end), so start
// must be strictly before end.
func NewQuery(channel, startRaw, endRaw string) (Query, error) {
	if !IsAllowedChannel(strings.TrimSpace(channel)) || channel != strings.TrimSpace(channel) {
		return Query{}, ErrInvalidQuery
	}
	start, err := time.Parse(time.RFC3339, startRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	end, err := time.Parse(time.RFC3339, endRaw)
	if err != nil {
		return Query{}, ErrInvalidQuery
	}
	if !start.Before(end) {
		return Query{}, ErrInvalidQuery
	}
	return Query{
		Channel: channel,
		Start:   start.UTC(),
		End:     end.UTC(),
	}, nil
}

