	retry_count    INTEGER NOT NULL CHECK (retry_count >= 0),
	failure_reason TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_delivery_records_channel_time
	ON delivery_records (channel, occurred_at);
`

