	var ids []string
	for rows.Next() {
		var tpl template.Template
		if err := rows.Scan(&tpl.TemplateID, &tpl.Name, &tpl.Body, &tpl.Enabled); err != nil {
			rows.Close()
			return nil, fmt.Errorf("%w: %v", ErrStorageUnavailable, err)
		}
