	rec := doJSON(t, handler, http.MethodPost, "/api/v1/notification-templates", validTemplate)
	if rec.Code != http.StatusCreated {
		t.Fatalf("create status = %d body = %s", rec.Code, rec.Body.String())
	}
	var created map[string]any
	if err := json.Unmarshal(rec.Body.Bytes(), &created); err != nil {
		t.Fatalf("decode: %v", err)
	}
	if created["template_id"] != "tpl-1" || created["name"] != "Welcome" {
		t.Fatalf("trimmed fields mismatch: %s", rec.Body.String())
	}
	if created["body"] != "\n\thello\n" {
		t.Fatalf("body should be verbatim: %v", created["body"])
	}
	channels, _ := created["channels"].([]any)
	if len(channels) != 2 || channels[0] != "in_app" || channels[1] != "sms" {
		t.Fatalf("channels mismatch: %s", rec.Body.String())
	}
	if created["enabled"] != true {
		t.Fatalf("enabled mismatch: %s", rec.Body.String())
	}

	listed := doJSON(t, handler, http.MethodGet, "/api/v1/notification-templates", "")
	if listed.Code != http.StatusOK {
		t.Fatalf("list status = %d body = %s", listed.Code, listed.Body.String())
	}
	var listPayload struct {
		Templates []map[string]any `json:"templates"`
	}
	if err := json.Unmarshal(listed.Body.Bytes(), &listPayload); err != nil {
		t.Fatalf("decode list: %v", err)
	}
	if len(listPayload.Templates) != 1 {
		t.Fatalf("list = %s", listed.Body.String())
	}

	detail := doJSON(t, handler, http.MethodGet, "/api/v1/notification-templates/tpl-1", "")
	if detail.Code != http.StatusOK {
		t.Fatalf("detail status = %d body = %s", detail.Code, detail.Body.String())
	}
	var detailPayload map[string]any
	if err := json.Unmarshal(detail.Body.Bytes(), &detailPayload); err != nil {
		t.Fatalf("decode detail: %v", err)
	}
	if detailPayload["template_id"] != "tpl-1" {
		t.Fatalf("detail missing template fields: %s", detail.Body.String())
	}
	summary, ok := detailPayload["delivery_summary"].(map[string]any)
	if !ok {
		t.Fatalf("detail missing delivery_summary: %s", detail.Body.String())
	}
	if summary["total_attempts"].(float64) != 0 {
		t.Fatalf("empty summary total = %v", summary["total_attempts"])
	}
	if summary["retry_count_min"] != nil || summary["retry_count_max"] != nil {
		t.Fatalf("empty bounds must be null: %s", detail.Body.String())
	}
	statusCounts, _ := summary["status_counts"].(map[string]any)
	for _, status := range []string{"pending", "retrying", "succeeded", "failed"} {
		if statusCounts[status].(float64) != 0 {
			t.Fatalf("status %s count = %v", status, statusCounts[status])
		}
	}
	reasons, _ := summary["failure_reasons"].([]any)
	if len(reasons) != 0 {
		t.Fatalf("failure reasons = %v", reasons)
	}
}

