			t.Fatalf("create status = %d body = %s", rec.Code, rec.Body.String())
		}
	}
	create(`{"template_id":"tpl-b","name":"B","body":"b","channels":["sms","email"],"enabled":true}`)
	create(`{"template_id":"tpl-a","name":"A","body":"a","channels":["push"],"enabled":false}`)
	create(`{"template_id":"tpl-c","name":"C","body":"c","channels":["sms"],"enabled":false}`)

	ids := func(target string) []string {
		rec := doJSON(t, handler, http.MethodGet, target, "")
		if rec.Code != http.StatusOK {
			t.Fatalf("GET %s status = %d body = %s", target, rec.Code, rec.Body.String())
		}
		var payload struct {
			Templates []struct {
				TemplateID string `json:"template_id"`
			} `json:"templates"`
		}
		if err := json.Unmarshal(rec.Body.Bytes(), &payload); err != nil {
			t.Fatalf("decode: %v", err)
		}
		ids := make([]string, len(payload.Templates))
		for i, tpl := range payload.Templates {
			ids[i] = tpl.TemplateID
		}
		return ids
	}

	if got := ids("/api/v1/notification-templates"); len(got) != 3 || got[0] != "tpl-a" || got[1] != "tpl-b" || got[2] != "tpl-c" {
