		t.Fatalf("disabled templates = %v", got)
	}
	if got := ids("/api/v1/notification-templates?channel=email&enabled=false"); len(got) != 0 {
		t.Fatalf("email+disabled templates = %v", got)
	}

	for _, target := range []string{
		"/api/v1/notification-templates?channel=bogus",
		"/api/v1/notification-templates?channel=%20sms",
		"/api/v1/notification-templates?enabled=1",
		"/api/v1/notification-templates?enabled=",
	} {
		rec := doJSON(t, handler, http.MethodGet, target, "")
		if rec.Code != http.StatusBadRequest || errorCode(t, rec) != "INVALID_TEMPLATE_REQUEST" {
			t.Fatalf("GET %s status = %d code = %s", target, rec.Code, errorCode(t, rec))
